// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {SafeERC20, IERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";

import {PRECISION} from "@solarity/solidity-lib/utils/Globals.sol";

import {IDepositPool, IERC165} from "../interfaces/capital-protocol/IDepositPool.sol";
import {IRewardPool} from "../interfaces/capital-protocol/IRewardPool.sol";
import {IDistributor} from "../interfaces/capital-protocol/IDistributor.sol";

import {LockMultiplierMath} from "../libs/LockMultiplierMath.sol";
import {ReferrerLib} from "../libs/ReferrerLib.sol";

contract DepositPool is IDepositPool, OwnableUpgradeable, UUPSUpgradeable {
    using SafeERC20 for IERC20;
    using ReferrerLib for ReferrerData;
    using ReferrerLib for ReferrerTier[];

    uint128 constant DECIMAL = 1e18;

    bool public isNotUpgradeable;

    /** @dev Main stake token for the contract */
    address public depositToken;

    /**
     * @dev `L1SenderV2` contract address
     * v7 update, moved to the `Distributor` contract.
     */
    address public unusedStorage0;

    /**
     * @dev Contain information about reward pools. Removed in `DepositPool`,
     * v6 update, moved to the `RewardPool` contract.
     */
    Pool[] public unusedStorage1;

    /** @dev Contain internal data about the reward pools, necessary for calculations */
    mapping(uint256 => RewardPoolData) public rewardPoolsData;

    /** @dev Contain internal data about the users deposits, necessary for calculations */
    mapping(address => mapping(uint256 => UserData)) public usersData;

    /** @dev Contain total real deposited amount for `depositToken` */
    uint256 public totalDepositedInPublicPools;

    /**
     * @dev UPGRADE. `DistributionV4` storage updates, add pool limits.
     * Removed in `DepositPool`, v6 update, moved to `rewardPoolsProtocolDetails`
     */
    mapping(uint256 => RewardPoolLimits) public unusedStorage2;

    /** @dev UPGRADE `DistributionV5` storage updates, add referrers. */
    mapping(uint256 => ReferrerTier[]) public referrerTiers;
    mapping(address => mapping(uint256 => ReferrerData)) public referrersData;
    /** @dev UPGRADE `DistributionV5` end. */

    /** @dev UPGRADE `DistributionV6` storage updates, add addresses allowed to claim. Add whitelisted claim receivers. */
    mapping(uint256 => mapping(address => mapping(address => bool))) public claimSender;
    mapping(uint256 => mapping(address => address)) public claimReceiver;
    /** @dev UPGRADE `DistributionV6` end. */

    /** @dev UPGRADE `DepositPool`, v7. Storage updates, add few deposit pools. */
    /** @dev This flag determines whether the migration has been completed. */
    bool public isMigrationOver;

    /** @dev `Distributor` contract address. */
    address public distributor;

    /** @dev Contain information about rewards pools needed for this contract. */
    mapping(uint256 => RewardPoolProtocolDetails) public rewardPoolsProtocolDetails;

    /** @dev UPGRADE `DepositPool`, v7 end. */

    /**********************************************************************************************/
    /*** Init, IERC165                                                                          ***/
    /**********************************************************************************************/

    constructor() {
        _disableInitializers();
    }

    function DepositPool_init(address depositToken_, address distributor_) external initializer {
        __Ownable_init();
        __UUPSUpgradeable_init();

        depositToken = depositToken_;
        setDistributor(distributor_);
    }

    function supportsInterface(bytes4 interfaceId_) external pure returns (bool) {
        return interfaceId_ == type(IDepositPool).interfaceId || interfaceId_ == type(IERC165).interfaceId;
    }

    /**********************************************************************************************/
    /*** Global contract management functionality for the contract `owner()`                    ***/
    /**********************************************************************************************/

    function setDistributor(address value_) public onlyOwner {
        require(IERC165(value_).supportsInterface(type(IDistributor).interfaceId), "DR: invalid distributor address");

        distributor = value_;

        emit DistributorSet(value_);
    }

    function setRewardPoolProtocolDetails(
        uint256 rewardPoolIndex_,
        uint128 withdrawLockPeriodAfterStake_,
        uint128 claimLockPeriodAfterStake_,
        uint128 claimLockPeriodAfterClaim_,
        uint256 minimalStake_
    ) public onlyOwner {
        RewardPoolProtocolDetails storage rewardPoolProtocolDetails = rewardPoolsProtocolDetails[rewardPoolIndex_];

        rewardPoolProtocolDetails.withdrawLockPeriodAfterStake = withdrawLockPeriodAfterStake_;
        rewardPoolProtocolDetails.claimLockPeriodAfterStake = claimLockPeriodAfterStake_;
        rewardPoolProtocolDetails.claimLockPeriodAfterClaim = claimLockPeriodAfterClaim_;
        rewardPoolProtocolDetails.minimalStake = minimalStake_;

        emit RewardPoolsDataSet(
            rewardPoolIndex_,
            withdrawLockPeriodAfterStake_,
            claimLockPeriodAfterStake_,
            claimLockPeriodAfterClaim_,
            minimalStake_
        );
    }

    function migrate(uint256 rewardPoolIndex_) external onlyOwner {
        require(!isMigrationOver, "DS: the migration is over");
        if (totalDepositedInPublicPools == 0) {
            isMigrationOver = true;
            emit Migrated(rewardPoolIndex_);

            return;
        }

        IRewardPool rewardPool_ = IRewardPool(IDistributor(distributor).rewardPool());
        rewardPool_.onlyExistedRewardPool(rewardPoolIndex_);
        rewardPool_.onlyPublicRewardPool(rewardPoolIndex_);

        // Transfer yield to prevent the reward loss
        uint256 remainder_ = IERC20(depositToken).balanceOf(address(this)) - totalDepositedInPublicPools;
        require(remainder_ > 0, "DS: yield for token is zero");
        IERC20(depositToken).transfer(distributor, remainder_);

        IERC20(depositToken).approve(distributor, totalDepositedInPublicPools);
        IDistributor(distributor).supply(rewardPoolIndex_, address(this), totalDepositedInPublicPools);

        isMigrationOver = true;

        emit Migrated(rewardPoolIndex_);
    }

    function editReferrerTiers(uint256 rewardPoolIndex_, ReferrerTier[] calldata referrerTiers_) external onlyOwner {
        IRewardPool rewardPool_ = IRewardPool(IDistributor(distributor).rewardPool());
        rewardPool_.onlyExistedRewardPool(rewardPoolIndex_);

        delete referrerTiers[rewardPoolIndex_];

        uint256 lastAmount_;
        uint256 lastMultiplier_;
        for (uint256 i = 0; i < referrerTiers_.length; i++) {
            uint256 amount_ = referrerTiers_[i].amount;
            uint256 multiplier_ = referrerTiers_[i].multiplier;

            if (i != 0) {
                require(amount_ > lastAmount_, "DS: invalid referrer tiers (1)");
                require(multiplier_ > lastMultiplier_, "DS: invalid referrer tiers (2)");
            }

            referrerTiers[rewardPoolIndex_].push(referrerTiers_[i]);

            lastAmount_ = amount_;
            lastMultiplier_ = multiplier_;
        }

        emit ReferrerTiersEdited(rewardPoolIndex_, referrerTiers_);
    }

    function manageUsersInPrivateRewardPool(
        uint256 rewardPoolIndex_,
        address[] calldata users_,
        uint256[] calldata amounts_,
        uint128[] calldata claimLockEnds_,
        address[] calldata referrers_
    ) external onlyOwner {
        IRewardPool rewardPool_ = IRewardPool(IDistributor(distributor).rewardPool());
        rewardPool_.onlyExistedRewardPool(rewardPoolIndex_);
        rewardPool_.onlyNotPublicRewardPool(rewardPoolIndex_);

        require(users_.length == amounts_.length, "DS: invalid length");
        require(users_.length == claimLockEnds_.length, "DS: invalid length");
        require(users_.length == referrers_.length, "DS: invalid length");

        IDistributor(distributor).distributeRewards(rewardPoolIndex_);
        (uint256 currentPoolRate_, uint256 rewards_) = _getCurrentPoolRate(rewardPoolIndex_);

        // Update `rewardPoolsProtocolDetails`
        rewardPoolsProtocolDetails[rewardPoolIndex_].distributedRewards += rewards_;

        for (uint256 i; i < users_.length; ++i) {
            uint256 deposited_ = usersData[users_[i]][rewardPoolIndex_].deposited;

            if (deposited_ <= amounts_[i]) {
                _stake(
                    users_[i],
                    rewardPoolIndex_,
                    amounts_[i] - deposited_,
                    currentPoolRate_,
                    claimLockEnds_[i],
                    referrers_[i]
                );
            } else {
                _withdraw(users_[i], rewardPoolIndex_, deposited_ - amounts_[i], currentPoolRate_);
            }
        }
    }

    /**********************************************************************************************/
    /*** Stake, claim, withdraw, lock management                                                ***/
    /**********************************************************************************************/

    function setClaimSender(
        uint256 rewardPoolIndex_,
        address[] calldata senders_,
        bool[] calldata isAllowed_
    ) external {
        IRewardPool(IDistributor(distributor).rewardPool()).onlyExistedRewardPool(rewardPoolIndex_);
        require(senders_.length == isAllowed_.length, "DS: invalid array length");

        for (uint256 i = 0; i < senders_.length; ++i) {
            claimSender[rewardPoolIndex_][_msgSender()][senders_[i]] = isAllowed_[i];

            emit ClaimSenderSet(rewardPoolIndex_, _msgSender(), senders_[i], isAllowed_[i]);
        }
    }

    function setClaimReceiver(uint256 rewardPoolIndex_, address receiver_) external {
        IRewardPool(IDistributor(distributor).rewardPool()).onlyExistedRewardPool(rewardPoolIndex_);

        claimReceiver[rewardPoolIndex_][_msgSender()] = receiver_;

        emit ClaimReceiverSet(rewardPoolIndex_, _msgSender(), receiver_);
    }

    function stake(uint256 rewardPoolIndex_, uint256 amount_, uint128 claimLockEnd_, address referrer_) external {
        IRewardPool rewardPool_ = IRewardPool(IDistributor(distributor).rewardPool());
        rewardPool_.onlyExistedRewardPool(rewardPoolIndex_);
        rewardPool_.onlyPublicRewardPool(rewardPoolIndex_);

        IDistributor(distributor).distributeRewards(rewardPoolIndex_);
        (uint256 currentPoolRate_, uint256 rewards_) = _getCurrentPoolRate(rewardPoolIndex_);

        _stake(_msgSender(), rewardPoolIndex_, amount_, currentPoolRate_, claimLockEnd_, referrer_);

        // Update `rewardPoolsProtocolDetails`
        rewardPoolsProtocolDetails[rewardPoolIndex_].distributedRewards += rewards_;
    }

    function withdraw(uint256 rewardPoolIndex_, uint256 amount_) external {
        IRewardPool rewardPool_ = IRewardPool(IDistributor(distributor).rewardPool());
        rewardPool_.onlyExistedRewardPool(rewardPoolIndex_);
        rewardPool_.onlyPublicRewardPool(rewardPoolIndex_);

        IDistributor(distributor).distributeRewards(rewardPoolIndex_);

        (uint256 currentPoolRate_, uint256 rewards_) = _getCurrentPoolRate(rewardPoolIndex_);

        _withdraw(_msgSender(), rewardPoolIndex_, amount_, currentPoolRate_);

        // Update `rewardPoolsProtocolDetails`
        rewardPoolsProtocolDetails[rewardPoolIndex_].distributedRewards += rewards_;
    }

    function claim(uint256 rewardPoolIndex_, address receiver_) external payable {
        _claim(rewardPoolIndex_, _msgSender(), receiver_);
    }

    function claimFor(uint256 rewardPoolIndex_, address staker_, address receiver_) external payable {
        if (claimReceiver[rewardPoolIndex_][staker_] != address(0)) {
            receiver_ = claimReceiver[rewardPoolIndex_][staker_];
        } else {
            require(claimSender[rewardPoolIndex_][staker_][_msgSender()], "DS: invalid caller");
        }

        _claim(rewardPoolIndex_, staker_, receiver_);
    }

    function claimReferrerTier(uint256 rewardPoolIndex_, address receiver_) external payable {
        _claimReferrerTier(rewardPoolIndex_, _msgSender(), receiver_);
    }

    function claimReferrerTierFor(uint256 rewardPoolIndex_, address referrer_, address receiver_) external payable {
        require(claimSender[rewardPoolIndex_][referrer_][_msgSender()], "DS: invalid caller");

        _claimReferrerTier(rewardPoolIndex_, referrer_, receiver_);
    }

    function lockClaim(uint256 rewardPoolIndex_, uint128 claimLockEnd_) external {
        require(isMigrationOver == true, "DS: migration isn't over");
        IRewardPool(IDistributor(distributor).rewardPool()).onlyExistedRewardPool(rewardPoolIndex_);

        require(claimLockEnd_ > block.timestamp, "DS: invalid lock end value (1)");

        IDistributor(distributor).distributeRewards(rewardPoolIndex_);

        address user_ = _msgSender();
        (uint256 currentPoolRate_, uint256 rewards_) = _getCurrentPoolRate(rewardPoolIndex_);

        RewardPoolData storage rewardPoolData = rewardPoolsData[rewardPoolIndex_];
        UserData storage userData = usersData[user_][rewardPoolIndex_];

        require(userData.deposited > 0, "DS: user isn't staked");
        require(claimLockEnd_ > userData.claimLockEnd, "DS: invalid lock end value (2)");

        userData.pendingRewards = _getCurrentUserReward(currentPoolRate_, userData);

        uint128 claimLockStart_ = userData.claimLockStart > 0 ? userData.claimLockStart : uint128(block.timestamp);
        uint256 multiplier_ = _getUserTotalMultiplier(claimLockStart_, claimLockEnd_, userData.referrer);
        uint256 virtualDeposited_ = (userData.deposited * multiplier_) / PRECISION;

        if (userData.virtualDeposited == 0) {
            userData.virtualDeposited = userData.deposited;
        }

        // Update `rewardPoolData`
        rewardPoolData.lastUpdate = uint128(block.timestamp);
        rewardPoolData.rate = currentPoolRate_;
        rewardPoolData.totalVirtualDeposited =
            rewardPoolData.totalVirtualDeposited +
            virtualDeposited_ -
            userData.virtualDeposited;

        // Update `userData`
        userData.rate = currentPoolRate_;
        userData.virtualDeposited = virtualDeposited_;
        userData.claimLockStart = claimLockStart_;
        userData.claimLockEnd = claimLockEnd_;
        // Update `rewardPoolsProtocolDetails`
        rewardPoolsProtocolDetails[rewardPoolIndex_].distributedRewards += rewards_;

        emit UserClaimLocked(rewardPoolIndex_, user_, claimLockStart_, claimLockEnd_);
    }

    function _stake(
        address user_,
        uint256 rewardPoolIndex_,
        uint256 amount_,
        uint256 currentPoolRate_,
        uint128 claimLockEnd_,
        address referrer_
    ) private {
        require(isMigrationOver == true, "DS: migration isn't over");

        RewardPoolProtocolDetails storage rewardPoolProtocolDetails = rewardPoolsProtocolDetails[rewardPoolIndex_];
        RewardPoolData storage rewardPoolData = rewardPoolsData[rewardPoolIndex_];
        UserData storage userData = usersData[user_][rewardPoolIndex_];

        if (claimLockEnd_ == 0) {
            claimLockEnd_ = userData.claimLockEnd > block.timestamp ? userData.claimLockEnd : uint128(block.timestamp);
        }
        require(claimLockEnd_ >= userData.claimLockEnd, "DS: invalid claim lock end");

        if (referrer_ == address(0)) {
            referrer_ = userData.referrer;
        }

        if (IRewardPool(IDistributor(distributor).rewardPool()).isRewardPoolPublic(rewardPoolIndex_)) {
            require(amount_ > 0, "DS: nothing to stake");

            amount_ = IDistributor(distributor).supply(rewardPoolIndex_, user_, amount_);
            require(userData.deposited + amount_ >= rewardPoolProtocolDetails.minimalStake, "DS: amount too low");

            totalDepositedInPublicPools += amount_;
        }

        userData.pendingRewards = _getCurrentUserReward(currentPoolRate_, userData);

        uint256 deposited_ = userData.deposited + amount_;
        uint256 multiplier_ = _getUserTotalMultiplier(uint128(block.timestamp), claimLockEnd_, referrer_);
        uint256 virtualDeposited_ = (deposited_ * multiplier_) / PRECISION;

        if (userData.virtualDeposited == 0) {
            userData.virtualDeposited = userData.deposited;
        }

        _applyReferrerTier(
            user_,
            rewardPoolIndex_,
            currentPoolRate_,
            userData.deposited,
            deposited_,
            userData.referrer,
            referrer_
        );

        // Update `poolData`
        rewardPoolData.lastUpdate = uint128(block.timestamp);
        rewardPoolData.rate = currentPoolRate_;
        rewardPoolData.totalVirtualDeposited =
            rewardPoolData.totalVirtualDeposited +
            virtualDeposited_ -
            userData.virtualDeposited;

        // Update `userData
        userData.lastStake = uint128(block.timestamp);
        userData.rate = currentPoolRate_;
        userData.deposited = deposited_;
        userData.virtualDeposited = virtualDeposited_;
        userData.claimLockStart = uint128(block.timestamp);
        userData.claimLockEnd = claimLockEnd_;
        userData.referrer = referrer_;

        emit UserStaked(rewardPoolIndex_, user_, amount_);
        emit UserClaimLocked(rewardPoolIndex_, user_, uint128(block.timestamp), claimLockEnd_);
    }

    function _withdraw(address user_, uint256 rewardPoolIndex_, uint256 amount_, uint256 currentPoolRate_) private {
        require(isMigrationOver == true, "DS: migration isn't over");

        RewardPoolProtocolDetails storage rewardPoolProtocolDetails = rewardPoolsProtocolDetails[rewardPoolIndex_];
        RewardPoolData storage rewardPoolData = rewardPoolsData[rewardPoolIndex_];
        UserData storage userData = usersData[user_][rewardPoolIndex_];

        uint256 deposited_ = userData.deposited;
        require(deposited_ > 0, "DS: user isn't staked");

        if (amount_ > deposited_) {
            amount_ = deposited_;
        }

        if (IRewardPool(IDistributor(distributor).rewardPool()).isRewardPoolPublic(rewardPoolIndex_)) {
            amount_ = IDistributor(distributor).withdraw(rewardPoolIndex_, user_, amount_);

            totalDepositedInPublicPools -= amount_;
        }

        uint256 newDeposited_;
        if (IRewardPool(IDistributor(distributor).rewardPool()).isRewardPoolPublic(rewardPoolIndex_)) {
            require(
                block.timestamp > userData.lastStake + rewardPoolProtocolDetails.withdrawLockPeriodAfterStake,
                "DS: pool withdraw is locked"
            );

            newDeposited_ = deposited_ - amount_;

            require(amount_ > 0, "DS: nothing to withdraw");

            // `newDeposited_ < 10`, where `10` is the minimal gap for the stETH token,
            // as the `IDistributor(distributor).withdraw(...)` allows that the actual
            // withdrawal amount may be less than the declared initial `amount_` due to rounding.
            require(
                newDeposited_ >= rewardPoolProtocolDetails.minimalStake || newDeposited_ < 10,
                "DS: invalid withdraw amount"
            );
        } else {
            newDeposited_ = deposited_ - amount_;
        }

        userData.pendingRewards = _getCurrentUserReward(currentPoolRate_, userData);

        uint256 multiplier_ = _getUserTotalMultiplier(
            uint128(block.timestamp),
            userData.claimLockEnd,
            userData.referrer
        );
        uint256 virtualDeposited_ = (newDeposited_ * multiplier_) / PRECISION;

        if (userData.virtualDeposited == 0) {
            userData.virtualDeposited = userData.deposited;
        }

        _applyReferrerTier(
            user_,
            rewardPoolIndex_,
            currentPoolRate_,
            deposited_,
            newDeposited_,
            userData.referrer,
            userData.referrer
        );

        // Update pool data
        rewardPoolData.lastUpdate = uint128(block.timestamp);
        rewardPoolData.rate = currentPoolRate_;
        rewardPoolData.totalVirtualDeposited =
            rewardPoolData.totalVirtualDeposited +
            virtualDeposited_ -
            userData.virtualDeposited;

        // Update user data
        userData.rate = currentPoolRate_;
        userData.deposited = newDeposited_;
        userData.virtualDeposited = virtualDeposited_;
        userData.claimLockStart = uint128(block.timestamp);

        emit UserWithdrawn(rewardPoolIndex_, user_, amount_);
    }

    function _claim(uint256 rewardPoolIndex_, address user_, address receiver_) private {
        require(isMigrationOver == true, "DS: migration isn't over");
        IRewardPool(IDistributor(distributor).rewardPool()).onlyExistedRewardPool(rewardPoolIndex_);

        UserData storage userData = usersData[user_][rewardPoolIndex_];

        require(
            block.timestamp >
                userData.lastStake + rewardPoolsProtocolDetails[rewardPoolIndex_].claimLockPeriodAfterStake,
            "DS: pool claim is locked (S)"
        );
        require(
            block.timestamp >
                userData.lastClaim + rewardPoolsProtocolDetails[rewardPoolIndex_].claimLockPeriodAfterClaim,
            "DS: pool claim is locked (C)"
        );
        require(block.timestamp > userData.claimLockEnd, "DS: user claim is locked");

        IDistributor(distributor).distributeRewards(rewardPoolIndex_);

        (uint256 currentPoolRate_, uint256 rewards_) = _getCurrentPoolRate(rewardPoolIndex_);
        uint256 pendingRewards_ = _getCurrentUserReward(currentPoolRate_, userData);
        require(pendingRewards_ > 0, "DS: nothing to claim");

        uint256 deposited_ = userData.deposited;

        uint256 multiplier_ = _getUserTotalMultiplier(0, 0, userData.referrer);
        uint256 virtualDeposited_ = (deposited_ * multiplier_) / PRECISION;

        if (userData.virtualDeposited == 0) {
            userData.virtualDeposited = userData.deposited;
        }

        // Update `rewardPoolData`
        RewardPoolData storage rewardPoolData = rewardPoolsData[rewardPoolIndex_];
        rewardPoolData.lastUpdate = uint128(block.timestamp);
        rewardPoolData.rate = currentPoolRate_;
        rewardPoolData.totalVirtualDeposited =
            rewardPoolData.totalVirtualDeposited +
            virtualDeposited_ -
            userData.virtualDeposited;

        // Update `userData`
        userData.rate = currentPoolRate_;
        userData.pendingRewards = 0;
        userData.virtualDeposited = virtualDeposited_;
        userData.claimLockStart = 0;
        userData.claimLockEnd = 0;
        userData.lastClaim = uint128(block.timestamp);
        // Update `rewardPoolsProtocolDetails`
        rewardPoolsProtocolDetails[rewardPoolIndex_].distributedRewards += rewards_;

        // Transfer rewards
        IDistributor(distributor).sendMintMessage{value: msg.value}(
            rewardPoolIndex_,
            receiver_,
            pendingRewards_,
            _msgSender()
        );

        emit UserClaimed(rewardPoolIndex_, user_, receiver_, pendingRewards_);
    }

    function _claimReferrerTier(uint256 rewardPoolIndex_, address referrer_, address receiver_) private {
        require(isMigrationOver == true, "DS: migration isn't over");

        IRewardPool(IDistributor(distributor).rewardPool()).onlyExistedRewardPool(rewardPoolIndex_);
        IDistributor(distributor).distributeRewards(rewardPoolIndex_);

        (uint256 currentPoolRate_, uint256 rewards_) = _getCurrentPoolRate(rewardPoolIndex_);

        RewardPoolProtocolDetails storage rewardPoolProtocolDetails = rewardPoolsProtocolDetails[rewardPoolIndex_];
        ReferrerData storage referrerData = referrersData[referrer_][rewardPoolIndex_];

        require(
            block.timestamp > referrerData.lastClaim + rewardPoolProtocolDetails.claimLockPeriodAfterClaim,
            "DS: pool claim is locked (C)"
        );

        uint256 pendingRewards_ = ReferrerLib.claimReferrerTier(referrerData, currentPoolRate_);

        // Update `rewardPoolData`
        RewardPoolData storage rewardPoolData = rewardPoolsData[rewardPoolIndex_];
        rewardPoolData.lastUpdate = uint128(block.timestamp);
        rewardPoolData.rate = currentPoolRate_;

        // Update `rewardPoolsProtocolDetails`
        rewardPoolsProtocolDetails[rewardPoolIndex_].distributedRewards += rewards_;

        // Transfer rewards
        IDistributor(distributor).sendMintMessage{value: msg.value}(
            rewardPoolIndex_,
            receiver_,
            pendingRewards_,
            _msgSender()
        );

        emit ReferrerClaimed(rewardPoolIndex_, referrer_, receiver_, pendingRewards_);
    }

    function _applyReferrerTier(
        address user_,
        uint256 rewardPoolIndex_,
        uint256 currentPoolRate_,
        uint256 oldDeposited_,
        uint256 newDeposited_,
        address oldReferrer_,
        address newReferrer_
    ) private {
        if (newReferrer_ == address(0)) {
            // we assume that referrer can't be removed, only changed
            return;
        }

        ReferrerData storage newReferrerData = referrersData[newReferrer_][rewardPoolIndex_];

        uint256 oldVirtualAmountStaked;
        uint256 newVirtualAmountStaked;

        if (oldReferrer_ == address(0)) {
            oldVirtualAmountStaked = newReferrerData.virtualAmountStaked;

            newReferrerData.applyReferrerTier(referrerTiers[rewardPoolIndex_], 0, newDeposited_, currentPoolRate_);
            newVirtualAmountStaked = newReferrerData.virtualAmountStaked;

            emit UserReferred(rewardPoolIndex_, user_, newReferrer_, newDeposited_);
        } else if (oldReferrer_ == newReferrer_) {
            oldVirtualAmountStaked = newReferrerData.virtualAmountStaked;

            newReferrerData.applyReferrerTier(
                referrerTiers[rewardPoolIndex_],
                oldDeposited_,
                newDeposited_,
                currentPoolRate_
            );
            newVirtualAmountStaked = newReferrerData.virtualAmountStaked;

            emit UserReferred(rewardPoolIndex_, user_, newReferrer_, newDeposited_);
        } else {
            ReferrerData storage oldReferrerData = referrersData[oldReferrer_][rewardPoolIndex_];

            oldVirtualAmountStaked = oldReferrerData.virtualAmountStaked + newReferrerData.virtualAmountStaked;

            oldReferrerData.applyReferrerTier(referrerTiers[rewardPoolIndex_], oldDeposited_, 0, currentPoolRate_);
            newReferrerData.applyReferrerTier(referrerTiers[rewardPoolIndex_], 0, newDeposited_, currentPoolRate_);
            newVirtualAmountStaked = oldReferrerData.virtualAmountStaked + newReferrerData.virtualAmountStaked;

            emit UserReferred(rewardPoolIndex_, user_, oldReferrer_, 0);
            emit UserReferred(rewardPoolIndex_, user_, newReferrer_, newDeposited_);
        }

        RewardPoolData storage rewardPoolData = rewardPoolsData[rewardPoolIndex_];
        rewardPoolData.totalVirtualDeposited =
            rewardPoolData.totalVirtualDeposited +
            newVirtualAmountStaked -
            oldVirtualAmountStaked;
    }

    /**********************************************************************************************/
    /*** Functionality for rewards calculations + getters                                       ***/
    /**********************************************************************************************/

    function getLatestUserReward(uint256 rewardPoolIndex_, address user_) public view returns (uint256) {
        if (!IRewardPool(IDistributor(distributor).rewardPool()).isRewardPoolExist(rewardPoolIndex_)) {
            return 0;
        }

        UserData storage userData = usersData[user_][rewardPoolIndex_];
        (uint256 currentPoolRate_, ) = _getCurrentPoolRate(rewardPoolIndex_);

        return _getCurrentUserReward(currentPoolRate_, userData);
    }

    function getLatestReferrerReward(uint256 rewardPoolIndex_, address user_) public view returns (uint256) {
        if (!IRewardPool(IDistributor(distributor).rewardPool()).isRewardPoolExist(rewardPoolIndex_)) {
            return 0;
        }

        (uint256 currentPoolRate_, ) = _getCurrentPoolRate(rewardPoolIndex_);

        return referrersData[user_][rewardPoolIndex_].getCurrentReferrerReward(currentPoolRate_);
    }

    function _getCurrentUserReward(uint256 currentPoolRate_, UserData memory userData_) private pure returns (uint256) {
        uint256 deposited_ = userData_.virtualDeposited == 0 ? userData_.deposited : userData_.virtualDeposited;

        uint256 newRewards_ = ((currentPoolRate_ - userData_.rate) * deposited_) / PRECISION;

        return userData_.pendingRewards + newRewards_;
    }

    function _getCurrentPoolRate(uint256 rewardPoolIndex_) private view returns (uint256, uint256) {
        RewardPoolData storage rewardPoolData = rewardPoolsData[rewardPoolIndex_];

        uint256 rewards_ = IDistributor(distributor).getDistributedRewards(rewardPoolIndex_, address(this)) -
            rewardPoolsProtocolDetails[rewardPoolIndex_].distributedRewards;

        if (rewardPoolData.totalVirtualDeposited == 0) {
            return (rewardPoolData.rate, rewards_);
        }

        uint256 rate_ = rewardPoolData.rate + (rewards_ * PRECISION) / rewardPoolData.totalVirtualDeposited;

        return (rate_, rewards_);
    }

    /**********************************************************************************************/
    /*** Functionality for multipliers, getters                                                 ***/
    /**********************************************************************************************/

    function getCurrentUserMultiplier(uint256 rewardPoolIndex_, address user_) public view returns (uint256) {
        if (!IRewardPool(IDistributor(distributor).rewardPool()).isRewardPoolExist(rewardPoolIndex_)) {
            return PRECISION;
        }

        UserData storage userData = usersData[user_][rewardPoolIndex_];

        return _getUserTotalMultiplier(userData.claimLockStart, userData.claimLockEnd, userData.referrer);
    }

    function getReferrerMultiplier(uint256 rewardPoolIndex_, address referrer_) public view returns (uint256) {
        if (!IRewardPool(IDistributor(distributor).rewardPool()).isRewardPoolExist(rewardPoolIndex_)) {
            return 0;
        }

        ReferrerData storage referrerData = referrersData[referrer_][rewardPoolIndex_];
        if (referrerData.amountStaked == 0) {
            return 0;
        }

        return (referrerData.virtualAmountStaked * PRECISION) / referrerData.amountStaked;
    }

    function _getUserTotalMultiplier(
        uint128 claimLockStart_,
        uint128 claimLockEnd_,
        address referrer_
    ) internal pure returns (uint256) {
        return
            LockMultiplierMath.getLockPeriodMultiplier(claimLockStart_, claimLockEnd_) +
            ReferrerLib.getReferralMultiplier(referrer_) -
            PRECISION;
    }

    /**********************************************************************************************/
    /*** UUPS                                                                                   ***/
    /**********************************************************************************************/

    function removeUpgradeability() external onlyOwner {
        isNotUpgradeable = true;
    }

    function version() external pure returns (uint256) {
        return 7;
    }

    function _authorizeUpgrade(address) internal view override onlyOwner {
        require(!isNotUpgradeable, "DS: upgrade isn't available");
    }
}

contracts/interfaces/capital-protocol/ID.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC165} from "@openzeppelin/contracts/utils/introspection/ERC165.sol";
import {IReferrer} from "./IReferrer.sol";

/**
 * @title IDepositPool
 * @notice Defines the basic interface for the DepositPool
 */
interface IDepositPool is IERC165, IReferrer {
    /**
     * @notice The structure that stores the reward pool rate data.
     * @param lastUpdate The timestamp when the pool was last updated.
     * @param rate The current reward rate. Variable used for internal calculations.
     * @param totalVirtualDeposited The total amount of tokens deposited in the pool with the users power factor.
     */
    struct RewardPoolData {
        uint128 lastUpdate;
        uint256 rate;
        uint256 totalVirtualDeposited;
    }

    /**
     * @notice The structure that stores the additional reward pool data.
     * @param withdrawLockPeriodAfterStake The period in seconds when the user can't withdraw his stake after the `stake()`.
     * @param claimLockPeriodAfterStake The period in seconds when the user can't claim tokens after the `stake()`.
     * @param claimLockPeriodAfterClaim The period in seconds when the user can't claim tokens after thr `claim()`.
     * @param minimalStake The minimal stake amount that user should have on the contract balance, after the stake or withdraw.
     * @param distributedRewards Distributed reward amount for all reward pool.
     */
    struct RewardPoolProtocolDetails {
        uint128 withdrawLockPeriodAfterStake;
        uint128 claimLockPeriodAfterStake;
        uint128 claimLockPeriodAfterClaim;
        uint256 minimalStake;
        uint256 distributedRewards;
    }

    /**
     * @notice The structure that stores the user data of the `DepositPool`.
     * @param lastStake The timestamp when the user last staked the `depositToken`.
     * @param deposited The amount of tokens deposited by user in the `DepositPool`.
     * @param rate The current reward rate. Used for internal calculations.
     * @param pendingRewards Number of rewards accrued to the user. Is not the final reward at a given time. Used for internal calculations.
     * @param claimLockStart The timestamp when the user locked his rewards.
     * @param claimLockEnd The timestamp when the user can claim his rewards.
     * @param virtualDeposited The amount of tokens deposited in the pool with user power factor.
     * @param lastClaim A timestamp of the last time the user call the `claim()`.
     * @param referrer The user referrer address.
     */
    struct UserData {
        uint128 lastStake;
        uint256 deposited;
        uint256 rate;
        uint256 pendingRewards;
        // `DistributionV2` storage updates
        uint128 claimLockStart;
        uint128 claimLockEnd;
        uint256 virtualDeposited;
        // `DistributionV4` storage updates
        uint128 lastClaim;
        // `DistributionV5` storage updates
        address referrer;
    }

    /**
     * @notice The event that is emitted when the `Distributor` contract address set.
     * @param distributor The `Distributor` contract address.
     */
    event DistributorSet(address distributor);

    /**
     * @notice The event that is emitted when the `Distributor` contract address set.
     * @param rewardPoolIndex The reward pool index.
     * @param withdrawLockPeriodAfterStake The period in seconds when the user can't withdraw his stake after the `stake()`.
     * @param claimLockPeriodAfterStake The period in seconds when the user can't claim tokens after the `stake()`.
     * @param claimLockPeriodAfterClaim The period in seconds when the user can't claim tokens after thr `claim()`.
     * @param minimalStake The minimal stake amount that user should have on the contract balance, after the stake or withdraw.
     */
    event RewardPoolsDataSet(
        uint256 rewardPoolIndex,
        uint128 withdrawLockPeriodAfterStake,
        uint128 claimLockPeriodAfterStake,
        uint128 claimLockPeriodAfterClaim,
        uint256 minimalStake
    );

    /**
     * @notice The event that is emitted when the `migrate()` function executed.
     * @param rewardPoolIndex The reward pool index for the public reward pool.
     */
    event Migrated(uint256 rewardPoolIndex);

    /**
     * @notice The event that is emitted when the pool referrers tiers are edited.
     * @param rewardPoolIndex The reward pool index.
     * @param tiers The referrers tiers.
     */
    event ReferrerTiersEdited(uint256 indexed rewardPoolIndex, ReferrerTier[] tiers);

    /**
     * @notice The event that is emitted when the user stakes tokens in the pool.
     * @param rewardPoolIndex The reward pool index.
     * @param user The user's address.
     * @param amount The amount of staked tokens.
     */
    event UserStaked(uint256 indexed rewardPoolIndex, address indexed user, uint256 amount);

    /**
     * @notice The event that is emitted when the user claims rewards from the pool.
     * @param rewardPoolIndex The reward pool index.
     * @param user The user's address.
     * @param receiver The receiver's address.
     * @param amount The amount of tokens.
     */
    event UserClaimed(uint256 indexed rewardPoolIndex, address indexed user, address receiver, uint256 amount);

    /**
     * @notice The event that is emitted when the referrer claims rewards.
     * @param rewardPoolIndex The reward pool index.
     * @param user The user's address.
     * @param receiver The reward receiver's address.
     * @param amount The amount of claimed rewards.
     */
    event ReferrerClaimed(uint256 indexed rewardPoolIndex, address indexed user, address receiver, uint256 amount);

    /**
     * @notice The event that is emitted when the user withdraws tokens from the pool.
     * @param rewardPoolIndex The reward pool index.
     * @param user The user's address.
     * @param amount The amount of tokens to withdraw.
     */
    event UserWithdrawn(uint256 indexed rewardPoolIndex, address indexed user, uint256 amount);

    /**
     * @notice The event that is emitted when the user locks his rewards.
     * @param rewardPoolIndex The reward pool index.
     * @param user The user's address.
     * @param claimLockStart The timestamp when the user locked his rewards.
     * @param claimLockEnd The timestamp when the user can claim his rewards.
     */
    event UserClaimLocked(
        uint256 indexed rewardPoolIndex,
        address indexed user,
        uint128 claimLockStart,
        uint128 claimLockEnd
    );

    /**
     * @notice The event that is emitted when the address allowed to claim set.
     * @param holder Address who add allowance.
     * @param caller Claim caller.
     * @param isAllowed Allowed or not.
     */
    event AddressAllowedToClaimSet(address holder, address caller, bool isAllowed);

    /**
     * @notice The event that is emitted when the user is referred.
     * @param rewardPoolIndex The reward pool index.
     * @param user The user's address.
     * @param referrer The referrer's address.
     * @param amount The amount of tokens.
     */
    event UserReferred(uint256 indexed rewardPoolIndex, address indexed user, address indexed referrer, uint256 amount);

    /**
     * @notice The event that is emitted when the claim sender set.
     * @param rewardPoolIndex The reward pool index.
     * @param staker The staker's address.
     * @param sender The `_msgSender()` address.
     * @param isAllowed True - when `sender` can claim against `staker`.
     */
    event ClaimSenderSet(uint256 rewardPoolIndex, address staker, address sender, bool isAllowed);

    /**
     * @notice The event that is emitted when the claim receiver set.
     * @param rewardPoolIndex The reward pool index.
     * @param staker The staker's address.
     * @param receiver The L2 receiver address.
     */
    event ClaimReceiverSet(uint256 rewardPoolIndex, address staker, address receiver);

    /**
     * @notice The function to receive the possibility to upgrade the contract.
     * @return The `false` when contract can be upgraded.
     */
    function isNotUpgradeable() external view returns (bool);

    /**
     * @notice The function to receive the deposit token (stETH, wBTC...).
     * @return The deposit token.
     */
    function depositToken() external view returns (address);

    /**
     * @notice The function to receive the total deposited in public pool amount of deposit token.
     * @return The total deposited in public pool amount.
     */
    function totalDepositedInPublicPools() external view returns (uint256);

    /**
     * @notice The function to receive the migration end flag.
     * @return The `true`, when end.
     */
    function isMigrationOver() external view returns (bool);

    /**
     * @notice The function to receive the `Distributor` contract address.
     * @return The `Distributor` contract address.
     */
    function distributor() external view returns (address);

    /**
     * @notice The function to initialize the contract.

     * @param depositToken_ The address of the deposit token. Users stake this token.
     * @param distributor_ The `Distributor` contract address.
     */
    function DepositPool_init(address depositToken_, address distributor_) external;

    /**
     * @notice The function to set the the `Distributor` contract address.
     * @dev Only for the contract `owner()`.
     * @param value_ The `Distributor` contract address.
     */
    function setDistributor(address value_) external;

    /**
     * @notice The function to fill the `RewardPoolProtocolDetails` struct.
     * @dev Only for the contract `owner()`.
     * @param rewardPoolIndex_ The reward pool index.
     * @param withdrawLockPeriodAfterStake_ The period in seconds when the user can't withdraw his stake after the `stake()`.
     * @param claimLockPeriodAfterStake_ The period in seconds when the user can't claim tokens after the `stake()`.
     * @param claimLockPeriodAfterClaim_ The period in seconds when the user can't claim tokens after thr `claim()`.
     * @param minimalStake_ The minimal stake amount that user should have on the contract balance, after the stake or withdraw.
     */
    function setRewardPoolProtocolDetails(
        uint256 rewardPoolIndex_,
        uint128 withdrawLockPeriodAfterStake_,
        uint128 claimLockPeriodAfterStake_,
        uint128 claimLockPeriodAfterClaim_,
        uint256 minimalStake_
    ) external;

    /**
     * @notice The function to migrate contract data to the new version. From V6 to V7.
     * @dev Only for the contract `owner()`.
     * @param rewardPoolIndex_ The reward pool index for the public reward pool.
     */
    function migrate(uint256 rewardPoolIndex_) external;

    /**
     * @notice The function to update the referrer tiers.
     * @dev Only for the contract `owner()`.
     * @param rewardPoolIndex_ The reward pool index.
     * @param referrerTiers_ The referrers tiers.
     */
    function editReferrerTiers(uint256 rewardPoolIndex_, ReferrerTier[] calldata referrerTiers_) external;

    /**
     * @notice The function to manage users and their stake amount in the private pools.
     * @dev Only for the contract `owner()`.
     * @param rewardPoolIndex_ The private reward poll index.
     * @param users_ The array of users.
     * @param amounts_ The array of final staked amount.
     * @param claimLockEnds_ The array of claim lock ends.
     * @param referrers_ The array of referrers.
     */
    function manageUsersInPrivateRewardPool(
        uint256 rewardPoolIndex_,
        address[] calldata users_,
        uint256[] calldata amounts_,
        uint128[] calldata claimLockEnds_,
        address[] calldata referrers_
    ) external;

    /**
     * @notice The function to set the addresses which can claim against initial staker.
     * @param rewardPoolIndex_ The reward poll index.
     * @param senders_  The addresses list
     * @param isAllowed_ Allowed or not
     */
    function setClaimSender(uint256 rewardPoolIndex_, address[] calldata senders_, bool[] calldata isAllowed_) external;

    /**
     * @notice The function to set the addresses to receive rewards when call is from any `_msgSender()`.
     * @param rewardPoolIndex_ The reward poll index.
     * @param receiver_  The receiver address
     */
    function setClaimReceiver(uint256 rewardPoolIndex_, address receiver_) external;

    /**
     * @notice The function to stake the `depositToken` tokens in the public pool.
     * @param rewardPoolIndex_ The public reward poll index.
     * @param amount_ The amount of tokens to stake.
     * @param claimLockEnd_ The timestamp when the user can claim his rewards. The default value is zero.
     * @param referrer_ The referrer address. The default value is zero address.
     */
    function stake(uint256 rewardPoolIndex_, uint256 amount_, uint128 claimLockEnd_, address referrer_) external;

    /**
     * @notice The function to withdraw tokens from the public pool.
     * @param rewardPoolIndex_ The public reward poll index.
     * @param amount_ The amount of tokens to withdraw.
     */
    function withdraw(uint256 rewardPoolIndex_, uint256 amount_) external;

    /**
     * @notice The function to claim rewards from the pool.
     * @param rewardPoolIndex_ The reward poll index.
     * @param receiver_ The rewards receiver's address.
     */
    function claim(uint256 rewardPoolIndex_, address receiver_) external payable;

    /**
     * @notice The function to claim rewards from the pool for the specified staker.
     * @dev The caller should be whitelisted with `setAddressesAllowedToClaim()`.
     * @param poolId_ The pool's id.
     * @param user_ Specified address.
     * @param receiver_ The rewards receiver's address.
     */
    function claimFor(uint256 poolId_, address user_, address receiver_) external payable;

    /**
     * @notice The function to claim referrer rewards from the pool.
     * @param poolId_ The pool's id.
     * @param receiver_ The rewards receiver's address.
     */
    function claimReferrerTier(uint256 poolId_, address receiver_) external payable;

    /**
     * @notice The function to claim referrer rewards from the pool for the specified referrer.
     * @dev The caller should be whitelisted with `setAddressesAllowedToClaim()`.
     * @param poolId_ The pool's id.
     * @param referrer_ Specified referrer.
     * @param receiver_ The rewards receiver's address.
     */
    function claimReferrerTierFor(uint256 poolId_, address referrer_, address receiver_) external payable;

    /**
     * @notice The function to lock rewards and receive power factors.
     * @param rewardPoolIndex_ The reward poll index.
     * @param claimLockEnd_ The timestamp when the user can claim his rewards.
     */
    function lockClaim(uint256 rewardPoolIndex_, uint128 claimLockEnd_) external;

    /**
     * @notice The function to get the latest user's reward for the specified pool.
     * @param rewardPoolIndex_ The reward poll index.
     * @param user_ The user's address.
     * @return The amount of latest user's rewards.
     */
    function getLatestUserReward(uint256 rewardPoolIndex_, address user_) external view returns (uint256);

    /**
     * @notice The function to get the latest referrer's reward for the specified pool.
     * @param rewardPoolIndex_ The reward poll index.
     * @param user_ The user's address.
     * @return The amount of latest referrer's rewards.
     */
    function getLatestReferrerReward(uint256 rewardPoolIndex_, address user_) external view returns (uint256);

    /**
     * @notice The function to get the current user power factor.
     * @param rewardPoolIndex_ The reward poll index.
     * @param user_ The user's address.
     * @return The current user multiplier.
     */
    function getCurrentUserMultiplier(uint256 rewardPoolIndex_, address user_) external view returns (uint256);

    /**
     * @notice The function to get the current referrer's power factor
     * @param rewardPoolIndex_ The reward poll index.
     * @param referrer_ The referrer's address.
     * @return The current referrer multiplier.
     */
    function getReferrerMultiplier(uint256 rewardPoolIndex_, address referrer_) external view returns (uint256);

    /**
     * @notice The function to remove the contract upgradeability.
     * @dev Only for the contract `owner()`.
     */
    function removeUpgradeability() external;

    /**
     * @notice The function to get the contract version.
     * @return The current contract version
     */
    function version() external pure returns (uint256);

    /** @dev Deprecated in the v6 update. */
    struct Pool {
        uint128 payoutStart;
        uint128 decreaseInterval;
        uint128 withdrawLockPeriod;
        uint128 claimLockPeriod;
        uint128 withdrawLockPeriodAfterStake;
        uint256 initialReward;
        uint256 rewardDecrease;
        uint256 minimalStake;
        bool isPublic;
    }

    /** @dev Deprecated in the v6 update. */
    struct RewardPoolLimits {
        uint128 claimLockPeriodAfterStake;
        uint128 claimLockPeriodAfterClaim;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC165} from "@openzeppelin/contracts/utils/introspection/ERC165.sol";
import {IReferrer} from "./IReferrer.sol";

/**
 * @title IDistributor
 * @notice Defines the basic interface for the Distributor
 */
interface IDistributor is IERC165 {
    event ChainLinkDataConsumerSet(address chainLinkDataConsumer);
    event L1SenderSet(address l1Sender);
    event AavePoolDataProviderSet(address aavePoolDataProvider);
    event AavePoolAddressesProviderSet(address aavePoolAddressesProvider);
    event AaveRewardsControllerSet(address aaveRewardsController);
    event RewardPoolSet(address rewardPool);
    event MinRewardsDistributePeriodSet(uint256 minRewardsDistributePeriod);
    event RewardPoolLastCalculatedTimestampSet(uint256 rewardPoolIndex_, uint128 rewardPoolLastCalculatedTimestamp);
    event DepositPoolAdded(uint256 rewardPoolIndex, DepositPool depositPool);
    event TokenPriceSet(string chainLinkPath, uint256 price);
    event AaveRewardsClaimed(address[] assets, uint256 amount, address to, address reward, uint256 claimedAmount);

    /**
     * @notice The Yield strategy.
     * NONE - for tokens without yield strategy (stETH).
     * NO_YIELD - for virtual tokens in the private pools.
     * AAVE - fot tokens with Aave yield strategy.
     */
    enum Strategy {
        NONE,
        NO_YIELD,
        AAVE
    }

    /**
     * @notice The struct that stores the DepositPool data.
     * @param token The yield token (stETH, wBTC...).
     * @param chainLinkPath The path from `ChainLinkDataConsumer`.
     * @param tokenPrice The last calculated token price. Used for internal calculations.
     * @param deposited The deposited `token` amount.
     * @param lastUnderlyingBalance The last calculated balance that include the `yield`.
     * @param strategy The `Strategy`.
     * @param aToken The `aToken` address for the pools with `AAVE` strategy. Zero for other.
     * @param isExist The existed flag. Should be true id deposit pool added.
     */
    struct DepositPool {
        address token;
        string chainLinkPath;
        uint256 tokenPrice;
        uint256 deposited;
        uint256 lastUnderlyingBalance;
        Strategy strategy;
        address aToken;
        bool isExist;
    }

    /**
     * @notice The function to receive the `ChainLinkDataConsumer` contract address.
     * @return The `ChainLinkDataConsumer` contract address.
     */
    function chainLinkDataConsumer() external view returns (address);

    /**
     * @notice The function to receive the `RewardPool` contract address.
     * @return The `RewardPool` contract address.
     */
    function rewardPool() external view returns (address);

    /**
     * @notice The function to receive the `L1SenderV2` contract address.
     * @return The `L1SenderV2` contract address.
     */
    function l1Sender() external view returns (address);

    /**
     * @notice The function to receive the Aave `AaveProtocolDataProvider` contract address.
     * @return The Aave `AaveProtocolDataProvider` contract address.
     */
    function aavePoolDataProvider() external view returns (address);

    /**
     * @notice The function to receive the Aave `PoolAddressesProvider` contract address.
     * @return The Aave `PoolAddressesProvider` contract address.
     */
    function aavePoolAddressesProvider() external view returns (address);

    /**
     * @notice The function to receive the Aave `RewardsController` contract address.
     * @return The Aave `RewardsController` contract address.
     */
    function aaveRewardsController() external view returns (address);

    /**
     * @notice The function to receive the undistributed reward.
     * @return The undistributed reward.
     */
    function undistributedRewards() external view returns (uint256);

    /**
     * @notice The function to receive the minimal rewards distribute period.
     * @dev Accrual of rewards is done in intervals, the minimum interval is stored here.
     * @return The minimal rewards distribute period
     */
    function minRewardsDistributePeriod() external view returns (uint256);

    /**
     * @notice The function to set the `ChainLinkDataConsumer` contract.
     * @dev Only for the contract `owner()`.
     * @param value_ The `ChainLinkDataConsumer` address.
     */
    function setChainLinkDataConsumer(address value_) external;

    /**
     * @notice The function to set the `AavePoolDataProvider` contract.
     * @dev Only for the contract `owner()`.
     * @param value_ The `AavePoolDataProvider` address.
     */
    function setAavePoolDataProvider(address value_) external;

    /**
     * @notice The function to set the Aave `PoolAddressesProvider` contract.
     * @dev Only for the contract `owner()`.
     * @param value_ The Aave `PoolAddressesProvider` address.
     */
    function setAavePoolAddressesProvider(address value_) external;

    /**
     * @notice The function to set the Aave `RewardsController` contract.
     * @dev Only for the contract `owner()`.
     * @param value_ The Aave `RewardsController` address.
     */
    function setAaveRewardsController(address value_) external;

    /**
     * @notice The function to set the `RewardPool` contract.
     * @dev Only for the contract `owner()`.
     * @param value_ The `RewardPool` address.
     */
    function setRewardPool(address value_) external;

    /**
     * @notice The function to add new `DepositPool`.
     * @dev Only for the contract `owner()`.
     * @param rewardPoolIndex_ The reward pool index.
     * @param depositPoolAddress_ The `DepositPool` contract address.
     * @param token_ The yield token for the `DepositPool` contract.
     * @param chainLinkPath_ The path from the `ChainLinkDataConsumer`.
     * @param strategy_ The `Strategy`.
     */
    function addDepositPool(
        uint256 rewardPoolIndex_,
        address depositPoolAddress_,
        address token_,
        string memory chainLinkPath_,
        Strategy strategy_
    ) external;

    /**
     * @notice The function to update the token prices.
     * @param rewardPoolIndex_ The reward pool index.
     */
    function updateDepositTokensPrices(uint256 rewardPoolIndex_) external;

    /**
     * @notice The function to get the distributed rewards.
     * @param rewardPoolIndex_ The reward pool index.
     * @param depositPoolAddress_ The `DepositPool` contract address.
     * @return Distributed rewards amount.
     */
    function getDistributedRewards(
        uint256 rewardPoolIndex_,
        address depositPoolAddress_
    ) external view returns (uint256);

    /**
     * @notice The function to supply tokens to the contract.
     * @dev Only for deposit pools
     * @param rewardPoolIndex_ The reward pool index.
     * @param user_ The user's address.
     * @param amount_ The token amount.
     * @return The token amount.
     */
    function supply(uint256 rewardPoolIndex_, address user_, uint256 amount_) external returns (uint256);

    /**
     * @notice The function to withdraw tokens from the contract.
     * @dev Only for deposit pools
     * @param rewardPoolIndex_ The reward pool index.
     * @param user_ The user's address.
     * @param amount_ The token amount.
     * @return The token amount.
     */
    function withdraw(uint256 rewardPoolIndex_, address user_, uint256 amount_) external returns (uint256);

    /**
     * @notice The function to distribute rewards based on the tokens yield.
     * @param rewardPoolIndex_ The reward pool index.
     */
    function distributeRewards(uint256 rewardPoolIndex_) external;

    /**
     * The function to withdraw the yield.
     * @param rewardPoolIndex_ The reward pool index.
     * @param depositPoolAddress_ The `DepositPool` contract address.
     */
    function withdrawYield(uint256 rewardPoolIndex_, address depositPoolAddress_) external;

    /**
     * @notice The function to withdraw undistributed rewards.
     * @dev Only for the contract `owner()`.
     * @param user_ The rewards receiver address.
     * @param refundTo_ The address to refund the overpaid gas.
     */
    function withdrawUndistributedRewards(address user_, address refundTo_) external payable;

    /**
     * @notice The function to send the reward token mint message to the `L1SenderV2`.
     * @param rewardPoolIndex_ The reward pool index.
     * @param user_ The user's address receiver .
     * @param amount_ The amount of reward token to mint.
     * @param refundTo_ The address to refund the overpaid gas.
     */
    function sendMintMessage(
        uint256 rewardPoolIndex_,
        address user_,
        uint256 amount_,
        address refundTo_
    ) external payable;

    /**
     * @notice Claims rewards from Aave protocol for the specified assets.
     * @dev Only for the contract `owner()`.
     * @param assets Array of aToken addresses to claim rewards for
     * @param amount Amount of rewards to claim (use type(uint256).max for all available)
     * @param to Address that will receive the rewards
     * @param reward Address of the reward token
     * @return claimedAmount The amount of rewards actually claimed
     */
    function claimAaveRewards(
        address[] calldata assets,
        uint256 amount,
        address to,
        address reward
    ) external returns (uint256 claimedAmount);

    /**
     * @notice The function to get the contract version.
     * @return The current contract version
     */
    function version() external pure returns (uint256);
}

