            uint256 depositTokenBalanceAfter_ = IERC20(depositPool.token).balanceOf(address(this));

            yield_ = depositTokenBalanceBefore_ - depositTokenBalanceAfter_;
        }

        depositPool.lastUnderlyingBalance -= yield_;
